"use strict";(self.webpackChunksdp_meta_docs=self.webpackChunksdp_meta_docs||[]).push([[269],{4050:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","label":"Introduction","href":"/sdp-meta/docs/intro","docId":"intro","unlisted":false},{"type":"category","label":"Getting Started","items":[{"type":"link","label":"Quickstart","href":"/sdp-meta/docs/getting-started/quickstart","docId":"getting-started/quickstart","unlisted":false},{"type":"link","label":"Declarative Automation Bundles","href":"/sdp-meta/docs/getting-started/dabs","docId":"getting-started/dabs","unlisted":false},{"type":"link","label":"Interactive CLI","href":"/sdp-meta/docs/getting-started/cli","docId":"getting-started/cli","unlisted":false},{"type":"link","label":"Manual Job Setup","href":"/sdp-meta/docs/getting-started/manual","docId":"getting-started/manual","unlisted":false},{"type":"link","label":"Databricks App","href":"/sdp-meta/docs/getting-started/app","docId":"getting-started/app","unlisted":false},{"type":"link","label":"MCP Server","href":"/sdp-meta/docs/getting-started/mcp","docId":"getting-started/mcp","unlisted":false},{"type":"link","label":"Agent Skill","href":"/sdp-meta/docs/getting-started/agent-skill","docId":"getting-started/agent-skill","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/sdp-meta/docs/getting-started/"},{"type":"category","label":"Concepts","items":[{"type":"link","label":"SDP-META Architecture","href":"/sdp-meta/docs/concepts/architecture","docId":"concepts/architecture","unlisted":false},{"type":"link","label":"Dataflowspec","href":"/sdp-meta/docs/concepts/dataflowspec","docId":"concepts/dataflowspec","unlisted":false},{"type":"link","label":"Pipeline Chaining","href":"/sdp-meta/docs/concepts/pipeline-chaining","docId":"concepts/pipeline-chaining","unlisted":false},{"type":"link","label":"Data Quality","href":"/sdp-meta/docs/concepts/data-quality","docId":"concepts/data-quality","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/sdp-meta/docs/concepts/"},{"type":"category","label":"Reference","items":[{"type":"link","label":"Onboarding File Fields","href":"/sdp-meta/docs/reference/onboarding-fields","docId":"reference/onboarding-fields","unlisted":false},{"type":"link","label":"Silver Transformations Schema","href":"/sdp-meta/docs/reference/silver-transformations","docId":"reference/silver-transformations","unlisted":false},{"type":"link","label":"Data Quality Rules Schema","href":"/sdp-meta/docs/reference/dq-rules","docId":"reference/dq-rules","unlisted":false},{"type":"link","label":"CLI Commands","href":"/sdp-meta/docs/reference/cli-commands","docId":"reference/cli-commands","unlisted":false},{"type":"link","label":"DAB Bundle Parameters","href":"/sdp-meta/docs/reference/dab-parameters","docId":"reference/dab-parameters","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/sdp-meta/docs/reference/"},{"type":"category","label":"Guides","items":[{"type":"link","label":"Autoloader / Cloud Files","href":"/sdp-meta/docs/guides/autoloader","docId":"guides/autoloader","unlisted":false},{"type":"link","label":"Kafka & Event Hubs","href":"/sdp-meta/docs/guides/kafka-eventhub","docId":"guides/kafka-eventhub","unlisted":false},{"type":"link","label":"CDC with apply_changes","href":"/sdp-meta/docs/guides/cdc","docId":"guides/cdc","unlisted":false},{"type":"link","label":"Snapshot Ingestion","href":"/sdp-meta/docs/guides/snapshot","docId":"guides/snapshot","unlisted":false},{"type":"link","label":"Silver Fanout","href":"/sdp-meta/docs/guides/silver-fanout","docId":"guides/silver-fanout","unlisted":false},{"type":"link","label":"DLT Sink","href":"/sdp-meta/docs/guides/dlt-sink","docId":"guides/dlt-sink","unlisted":false},{"type":"link","label":"Multi-Source CDC","href":"/sdp-meta/docs/guides/multi-source-cdc","docId":"guides/multi-source-cdc","unlisted":false},{"type":"link","label":"Row Filters","href":"/sdp-meta/docs/guides/row-filters","docId":"guides/row-filters","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/sdp-meta/docs/guides/"},{"type":"category","label":"Operations","items":[{"type":"link","label":"Troubleshooting","href":"/sdp-meta/docs/operations/troubleshooting","docId":"operations/troubleshooting","unlisted":false},{"type":"link","label":"Integration Tests","href":"/sdp-meta/docs/operations/integration-tests","docId":"operations/integration-tests","unlisted":false},{"type":"link","label":"Migration: DLT-META to SDP-META","href":"/sdp-meta/docs/operations/migration","docId":"operations/migration","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/sdp-meta/docs/operations/"},{"type":"link","label":"Contributing","href":"/sdp-meta/docs/contributing/","docId":"contributing/index","unlisted":false},{"type":"link","label":"FAQ","href":"/sdp-meta/docs/faq","docId":"faq","unlisted":false},{"type":"link","label":"Changelog","href":"/sdp-meta/docs/changelog","docId":"changelog","unlisted":false}]},"docs":{"changelog":{"id":"changelog","title":"Changelog","description":"---","sidebar":"docsSidebar"},"concepts/architecture":{"id":"concepts/architecture","title":"SDP-META Architecture","description":"SDP-META is a metadata-driven framework for building Bronze and Silver data pipelines on Lakeflow Spark Declarative Pipelines. You define pipelines in an onboarding file (YAML or JSON); SDP-META reads that file and builds the full pipeline graph automatically.","sidebar":"docsSidebar"},"concepts/data-quality":{"id":"concepts/data-quality","title":"Data Quality","description":"SDP-META supports Lakeflow Spark Declarative Pipelines\' native Data Quality expectations. Define expectations in your onboarding YAML or JSON file; SDP-META registers and applies them at pipeline startup.","sidebar":"docsSidebar"},"concepts/dataflowspec":{"id":"concepts/dataflowspec","title":"Dataflowspec","description":"The onboarding file (YAML or JSON) is the configuration you write to define your pipelines. The Onboard Job reads it and writes the derived metadata into bronzedataflowspec and silverdataflowspec Delta tables, which the Generic Declarative Pipeline reads at runtime.","sidebar":"docsSidebar"},"concepts/index":{"id":"concepts/index","title":"Concepts","description":"Core concepts for SDP-META.","sidebar":"docsSidebar"},"concepts/pipeline-chaining":{"id":"concepts/pipeline-chaining","title":"Pipeline Chaining","description":"Pipeline chaining connects a Bronze pipeline (which writes Delta tables) to a Silver pipeline (which reads those tables as its source). SDP-META supports this through the layer=bronze_silver configuration and two deployment modes.","sidebar":"docsSidebar"},"contributing/index":{"id":"contributing/index","title":"Contributing","description":"We welcome contributions from the community. Whether you are fixing a bug, adding a feature, improving documentation, or writing tests, your help is appreciated.","sidebar":"docsSidebar"},"faq":{"id":"faq","title":"FAQ","description":"General","sidebar":"docsSidebar"},"getting-started/agent-skill":{"id":"getting-started/agent-skill","title":"Agent Skill","description":"SDP-META ships an Agent Skill \u2014 a portable, agent-facing operating manual that teaches an AI coding agent how to use SDP-META correctly: the onboarding metadata model, the onboard \u2192 deploy workflow, the DAB commands, and the common footguns. It is written in the Agent Skills format (a SKILL.md file plus supporting references), which is portable across agents \u2014 not tied to any single tool.","sidebar":"docsSidebar"},"getting-started/app":{"id":"getting-started/app","title":"Databricks App","description":"The SDP-META Databricks App is a browser-based GUI for onboarding,","sidebar":"docsSidebar"},"getting-started/cli":{"id":"getting-started/cli","title":"Interactive CLI","description":"The SDP-META CLI provides interactive commands to onboard and deploy pipelines without writing bundle YAML.","sidebar":"docsSidebar"},"getting-started/dabs":{"id":"getting-started/dabs","title":"Declarative Automation Bundles","description":"A Databricks Declarative Automation Bundle (DAB) declares jobs, pipelines, and configuration as code. SDP-META ships a DAB template for deploying the onboarding job and Lakeflow Spark Declarative Pipelines from git \u2014 no interactive wizards, and promoting from dev to prod is a single command.","sidebar":"docsSidebar"},"getting-started/index":{"id":"getting-started/index","title":"Getting Started","description":"SDP-META supports several deployment paths. All lead to the same outcome: a running Bronze/Silver pipeline driven by onboarding metadata.","sidebar":"docsSidebar"},"getting-started/manual":{"id":"getting-started/manual","title":"Manual Job Setup","description":"Configure the onboarding job and Declarative Pipeline manually through the Databricks UI or a notebook.","sidebar":"docsSidebar"},"getting-started/mcp":{"id":"getting-started/mcp","title":"MCP Server","description":"The SDP-META MCP (Model Context Protocol) server exposes local bundle","sidebar":"docsSidebar"},"getting-started/quickstart":{"id":"getting-started/quickstart","title":"Quickstart","description":"Get a SDP-META pipeline running using the DAB path with the --quickstart flag.","sidebar":"docsSidebar"},"guides/autoloader":{"id":"guides/autoloader","title":"Autoloader / Cloud Files","description":"SDP-META uses Databricks Autoloader (cloudFiles) to incrementally ingest files from cloud object storage. Autoloader tracks which files have been processed, making it suitable for continuously arriving data.","sidebar":"docsSidebar"},"guides/cdc":{"id":"guides/cdc","title":"CDC with apply_changes","description":"Use this pattern when your source system emits a CDC stream with insert, update, and delete events. SDP-META maps bronzecdcapplychanges and silvercdcapplychanges directly to the Declarative Pipeline createautocdc_flow API.","sidebar":"docsSidebar"},"guides/dlt-sink":{"id":"guides/dlt-sink","title":"DLT Sink","description":"The DLT Sink feature writes pipeline output to an external Delta table or Kafka topic outside the pipeline\'s managed storage. SDP-META maps bronzesink and silversink directly to the Declarative Pipeline Sink API.","sidebar":"docsSidebar"},"guides/index":{"id":"guides/index","title":"Guides","description":"| Scenario | Guide |","sidebar":"docsSidebar"},"guides/kafka-eventhub":{"id":"guides/kafka-eventhub","title":"Kafka & Event Hubs","description":"SDP-META supports streaming ingestion from Apache Kafka and Azure Event Hubs. Event Hubs uses the Kafka protocol endpoint, so both share the same underlying Spark Structured Streaming reader.","sidebar":"docsSidebar"},"guides/multi-source-cdc":{"id":"guides/multi-source-cdc","title":"Multi-Source CDC","description":"Multi-source CDC merges CDC events from multiple independent source paths into a single target table \u2014 for example, regional data feeds (US, EU, APAC) landing in separate S3 prefixes.","sidebar":"docsSidebar"},"guides/row-filters":{"id":"guides/row-filters","title":"Row Filters","description":"Row filters restrict which rows a pipeline materializes at runtime via the where_clause field in the silver transformations file.","sidebar":"docsSidebar"},"guides/silver-fanout":{"id":"guides/silver-fanout","title":"Silver Fanout","description":"Silver fanout is a topology where a single bronze table feeds multiple silver tables, each with its own transformation logic, filter conditions, and CDC configuration.","sidebar":"docsSidebar"},"guides/snapshot":{"id":"guides/snapshot","title":"Snapshot Ingestion","description":"Snapshot ingestion is for data sources that deliver full replacement files rather than incremental changes or CDC events. SDP-META maps snapshot ingestion to the Declarative Pipeline applychangesfrom_snapshot API, which compares each snapshot to the previous state to produce correct insert, update, and delete semantics.","sidebar":"docsSidebar"},"intro":{"id":"intro","title":"Introduction","description":"SDP-META is a metadata-driven framework for building automated Bronze and Silver data pipelines on Databricks Lakeflow Spark Declarative Pipelines. Define your pipelines in a JSON or YAML onboarding file; a single generic Declarative Pipeline builds the full processing graph automatically.","sidebar":"docsSidebar"},"operations/index":{"id":"operations/index","title":"Operations","description":"Guides for running, debugging, testing, and migrating SDP-META deployments.","sidebar":"docsSidebar"},"operations/integration-tests":{"id":"operations/integration-tests","title":"Integration Tests","description":"The SDP-META integration test suite runs end-to-end pipeline tests against a real Databricks workspace, covering cloudFiles, Event Hubs, and Kafka source types.","sidebar":"docsSidebar"},"operations/migration":{"id":"operations/migration","title":"Migration: DLT-META to SDP-META","description":"The project was renamed from DLT-META to SDP-META to align with current Databricks product terminology (Lakeflow Spark Declarative Pipelines). The rename took effect in v0.1.0.","sidebar":"docsSidebar"},"operations/troubleshooting":{"id":"operations/troubleshooting","title":"Troubleshooting","description":"Python version issues","sidebar":"docsSidebar"},"reference/cli-commands":{"id":"reference/cli-commands","title":"CLI Commands","description":"All SDP-META operations are available through the Databricks Labs CLI extension.","sidebar":"docsSidebar"},"reference/dab-parameters":{"id":"reference/dab-parameters","title":"DAB Bundle Parameters","description":"This page covers all parameters exposed when scaffolding a bundle with databricks labs sdp-meta bundle-init, and all keys in the generated resources/variables.yml.","sidebar":"docsSidebar"},"reference/dq-rules":{"id":"reference/dq-rules","title":"Data Quality Rules Schema","description":"Data quality rules are defined in a separate JSON or YAML file and referenced from the onboarding file via bronzedataqualityexpectationsjson or silverdataqualityexpectationsjson. Each rule is a named SQL boolean expression mapped directly to Declarative Pipeline constraint annotations.","sidebar":"docsSidebar"},"reference/index":{"id":"reference/index","title":"Reference","description":"Complete technical reference documentation for SDP-META.","sidebar":"docsSidebar"},"reference/onboarding-fields":{"id":"reference/onboarding-fields","title":"Onboarding File Fields","description":"The onboarding file is a JSON or YAML array of flow definitions. Each element describes one data flow \u2014 its source, bronze target, and optionally a silver target.","sidebar":"docsSidebar"},"reference/silver-transformations":{"id":"reference/silver-transformations","title":"Silver Transformations Schema","description":"The silver transformations file defines the SQL logic applied when writing from a bronze table to a silver table. Each entry maps one source to one silver target.","sidebar":"docsSidebar"}}}}')}}]);